select 
from edu_student


        and (student_name like concat('%', #{keyword}, '%')
            or student_code like concat('%', #{keyword}, '%')
            or phone like concat('%', #{keyword}, '%'))


        and study_mode = #{studyMode}


        and class_id = #{classId}


        and product_id = #{productId}


order by id desc

select , password
from edu_student
where phone = #{phone}

mapper.update:
update edu_student
set resume_parse_status = 'PROCESSING',
    resume_parse_error_message = null,
    updated_at = #{now}
where id = #{id}
  and resume_object_key = #{objectKey}
  and resume_parse_status = 'PENDING'

update edu_student
set resume_parse_status = 'SUCCESS',
    resume_text = #{resumeText},
    resume_parse_error_message = null,
    resume_parsed_at = #{now},
    updated_at = #{now}
where id = #{id}
  and resume_object_key = #{objectKey}

update edu_student
set resume_parse_status = 'FAILED',
    resume_parse_error_message = #{errorMessage},
    resume_parsed_at = #{now},
    updated_at = #{now}
where id = #{id}
  and resume_object_key = #{objectKey}
